  -- item 16: DIY build: Carl's DIY kit plus 1 in EMT from the hardware store
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$DIY$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$DIY build: Carl's DIY kit plus 1 in EMT from the hardware store$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$DIY build: Carl's DIY kit plus 1 in EMT from the hardware store$q$, $q$DIY (Carl's Place kit on self-cut EMT)$q$, $q$The builder-sharer: he posts the parts list, the total and the ceiling height, and the next asker copies it.$q$, $q$Two GSF builders put the all-in number at $1,006 and $1,263 and both said they would buy it again. That is the number the whole category gets measured against.$q$, $q$Pros: the cheapest brand-name screen-and-surround route on the forum; Carl's cut lengths leave enough pole inserted to tighten the screen (GSF 185585)
Cons: cutting EMT is the job nobody enjoys; the store will cut it if asked (GSF 211230 replies); 1 in EMT carries nothing overhead
Known issues: too-tight screen trampolines the ball back to head height (GSF 253998, 301022); wedges over the head off the top third; baffles 12 in wide spaced 16 in, foam behind the top half (GSF 264435); rough welds on fittings scratch floors (GSF 211230)
Room fit: Same as the kit: 9 ft of ceiling for the 8-ft frames; the forum's 8 ft 4 in garage build went to wood framing instead (GSF 321467).
