  -- item 17: DIY build: EMT frame, canopy fittings and a budget impact screen (the $500 blueprint)
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$DIY$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$DIY build: EMT frame, canopy fittings and a budget impact screen (the $500 blueprint)$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$DIY build: EMT frame, canopy fittings and a budget impact screen (the $500 blueprint)$q$, $q$DIY (EMT frame with a budget screen)$q$, $q$The under-$3k builder (GSF 147901: $2,954.25 whole sim) who would rather cut pipe than pay for a surround.$q$, $q$It is the build that proves the hobby before the money: $500 and a Saturday, then upgrade the screen when the bounce-back gets old.$q$, $q$Pros: frame for $200 to $275; sized to the room, not the catalogue
Cons: the fittings are the catch: hardware stores do not stock three-way corners; a budget single-layer screen bounces and shows wrinkles; no padding, surround or baffle unless you add them
Known issues: PVC frames shatter on direct hits (Yardstick, Gung Ho); bare metal pipe needs foam lagging (Yardstick)
Room fit: Cut the verticals to the ceiling you have; Yardstick says at least 5 ft of depth.
