  -- item 18: DIY build: hinged side panels or a frame that pivots into the ceiling
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$DIY$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$DIY build: hinged side panels or a frame that pivots into the ceiling$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$DIY build: hinged side panels or a frame that pivots into the ceiling$q$, $q$DIY (hinged or hoisted EMT)$q$, $q$The builder whose spouse 'refuses to give up half of our 2-car garage for a toy' (GSF 247350) and who owns a drill, a grinder and patience.$q$, $q$Before any product folded, people hinged Carl's side panels and hung the frame from the joists. The threads are old (2017 to 2023) and still get bumped, which says the problem never went away.$q$, $q$Pros: the car comes back; proven designs with photos on the forum
Cons: the engineering is on you (GSF 383722 reply); stainless connectors burned two drill bits before the builder switched to epoxy (GSF 247350); the swivel-fitting design in GSF 162427 was never built; the thread drifted to curtain track
Known issues: hoist and pivot builds need a safety catch; the Smart Home Hookup build added a linear rail in case the hoist fails
Room fit: The ceiling examples: 8 ft 6 in (GSF 247350 target), 9 ft 6 in (GSF 133261), 8 ft 6 in vaulted to 10 ft by cutting four trusses (Smart Home Hookup).
