  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, item_type, specs, photo_url, quantity, sort_index)
    VALUES (v_bag, v_section, $q$DIY build: ceiling-track curtain or pipe-and-drape with a hanging grommeted screen$q$, $q$DIY (curtain track, pipe-and-drape)$q$, $q$The garage that blocks a window or parks a car and will drill the ceiling but not build a frame.$q$, $q$It is the fold-away that costs the least and needs the most tinkering; the forum answer to 'can I keep the window' and 'can I keep the car' before the roller products existed.$q$, $q$Pros: the bay slides open in seconds; cheapest retractable route by far; Reddit's 208-upvote garage sim used a retractable screen with side rollers and hid the mat too (Sim Weekly)
