$seed$;

-- 6. Summary: one row per bag.
SELECT
  b.code,
  (SELECT count(*) FROM bag_sections s WHERE s.bag_id = b.id) AS sections,
  (SELECT count(*) FROM bag_items i WHERE i.bag_id = b.id) AS items,
  (SELECT count(*) FROM links l JOIN bag_items i ON i.id = l.bag_item_id WHERE i.bag_id = b.id) AS links
FROM bags b
WHERE b.owner_id = '2c3e503a-78ce-4a8d-ae37-60b4a16d916e'::uuid AND b.code IN ($q$sim-enclosures$q$)
ORDER BY b.code;

COMMIT;
